// Filter products where stock is at or below reorder threshold
const allProducts = $input.all();
const productsNeedingAlerts = allProducts.filter(item => {
  const product = item.json;
  return product.current_stock <= product.reorder_threshold;
});

// If no products need alerts, stop here
if (productsNeedingAlerts.length === 0) {
  return [{ json: { skip_workflow: true, products: [] } }];
}

// Prepare data for next node
const products = productsNeedingAlerts.map(item => item.json);

// Return one item per product (for Supabase filtering)
return products.map(product => ({
  json: {
    product_id: product.product_id,
    product_name: product.product_name,
    current_stock: product.current_stock,
    reorder_threshold: product.reorder_threshold,
    avg_daily_sales: product.avg_daily_sales,
    unit_price: product.unit_price,
    category: product.category,
    last_restock_date: product.last_restock_date
  }
}));

// === GET PRODUCTS NEEDING ALERTS ===
const inputData = $input.all();
let productsNeedingAlerts = [];

// Try to extract products from various possible formats
for (const item of inputData) {
  const data = item.json;

  // Check if this is wrapped data
  if (data.products_needing_alerts && Array.isArray(data.products_needing_alerts)) {
    productsNeedingAlerts = data.products_needing_alerts;
    break;
  }
  // Check if this is direct product data
  else if (data.product_id && data.current_stock !== undefined) {
    productsNeedingAlerts.push(data);
  }
}

if (productsNeedingAlerts.length === 0) {
  return [];
}

console.log(`Found ${productsNeedingAlerts.length} products needing alerts`);

// === GET EXISTING ALERTS ===
let existingAlerts = [];

// Method 1: Try to get from node reference
try {
  const fetchNode = $('Fetch Existing Alerts');
  if (fetchNode && fetchNode.all) {
    const alertData = fetchNode.all();
    existingAlerts = alertData.map(item => item.json);
    console.log(`Method 1: Found ${existingAlerts.length} existing alerts via $() reference`);
  }
} catch (e) {
  console.log('Method 1 failed:', e.message);
}

// Method 2: Try alternate node reference if Method 1 failed
if (existingAlerts.length === 0) {
  try {
    const alertData = $node["Fetch Existing Alerts"].all();
    existingAlerts = alertData.map(item => item.json);
    console.log(`Method 2: Found ${existingAlerts.length} existing alerts via $node reference`);
  } catch (e) {
    console.log('Method 2 failed:', e.message);
  }
}

console.log(`Total existing alerts: ${existingAlerts.length}`);

// Debug: Show first alert structure
if (existingAlerts.length > 0) {
  console.log('First alert:', JSON.stringify(existingAlerts[0], null, 2));
}

// === CREATE LOOKUP MAP ===
const alertsMap = new Map();

existingAlerts.forEach(alert => {
  if (alert.product_id) {
    alertsMap.set(alert.product_id, alert);
    console.log(`Mapped: ${alert.product_id} -> ${alert.id}`);
  }
});

console.log(`Alert map size: ${alertsMap.size}`);

// === DECIDE: CREATE OR UPDATE ===
const result = [];

productsNeedingAlerts.forEach(product => {
  const existingAlert = alertsMap.get(product.product_id);

  const alertData = {
    product_id: product.product_id,
    product_name: product.product_name,
    alert_name: `Low Stock Alert: ${product.product_name}`,
    alert_date: new Date().toISOString(),
    current_stock: product.current_stock,
    reorder_threshold: product.reorder_threshold,
    alert_status: "Active"
  };

  if (existingAlert && existingAlert.id) {
    // UPDATE
    console.log(`✓ UPDATE: ${product.product_id} (ID: ${existingAlert.id})`);
    result.push({
      json: {
        ...alertData,
        operation: 'update',
        alert_id: existingAlert.id
      }
    });
  } else {
    // CREATE
    console.log(`✓ CREATE: ${product.product_id} (no existing alert)`);
    result.push({
      json: {
        ...alertData,
        operation: 'create'
      }
    });
  }
});

console.log(`\n=== SUMMARY ===`);
console.log(`Total: ${result.length}`);
console.log(`Creates: ${result.filter(r => r.json.operation === 'create').length}`);
console.log(`Updates: ${result.filter(r => r.json.operation === 'update').length}`);

return result;
